std::priority_queue<int> lo;                                   // 大根堆，较小的一半
std::priority_queue<int, std::vector<int>, std::greater<int>> hi;  // 小根堆，较大的一半

void add(int x) {
    lo.push(x);
    hi.push(lo.top()); lo.pop();        // 把 lo 最大的挪给 hi
    if (hi.size() > lo.size()) {        // 平衡：lo 可以比 hi 多 1
        lo.push(hi.top()); hi.pop();
    }
}

double median() {
    if (lo.size() == hi.size()) return (lo.top() + hi.top()) / 2.0;
    return lo.top();
}

std::vector<int> h;                    // 小根堆

void sift_up(int i) {
    while (i > 0) {
        int p = (i - 1) / 2;
        if (h[p] <= h[i]) break;
        std::swap(h[p], h[i]);
        i = p;
    }
}

void sift_down(int i) {
    int n = h.size();
    while (true) {
        int c = 2 * i + 1, best = i;
        if (c < n && h[c] < h[best]) best = c;
        if (c + 1 < n && h[c + 1] < h[best]) best = c + 1;
        if (best == i) break;
        std::swap(h[i], h[best]);
        i = best;
    }
}

void push(int x) { h.push_back(x); sift_up(h.size() - 1); }

int pop() {
    int top = h[0];
    h[0] = h.back(); h.pop_back();
    if (!h.empty()) sift_down(0);
    return top;
}

// h 已填入数据，n = h.size()
for (int i = n / 2 - 1; i >= 0; --i) {
    sift_down(i);
}
